//! Canonical fieldset name DOMString reflection.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><fieldset id=fieldset name=group><legend>Group</legend><input value=seed></fieldset></form><form id=other></form><fieldset id=external form=other></fieldset></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://fieldset-metadata.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn fieldset_name_canonical_live_descriptor_and_raw_value(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),P=HTMLFieldSetElement.prototype,a=Object.getOwnPropertyDescriptor(P,'name');if(!a||typeof a.get!=='function'||typeof a.set!=='function'||a.get.name!=='get name'||a.set.name!=='set name'||a.get.length!==0||a.set.length!==1||!a.enumerable||!a.configurable||Object.hasOwn(x,'name'))throw 'canonical descriptor';if(x.name!=='group')throw 'parsed name';x.name='a\ud800b\udfff';if(x.name!=='a\ud800b\udfff'||x.getAttribute('name')!==x.name)throw 'exact name';x.setAttribute('name','attribute');if(x.name!=='attribute')throw 'live attribute';x.removeAttribute('name');if(x.name!=='')throw 'missing empty';"#);}
#[test]
fn fieldset_name_inert_namespace_clone_and_adoption(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',x=doc.createElementNS(html,'x:fieldset'),a=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'name');if(!a||x.name!=='')throw 'inert canonical name';x.setAttributeNS('urn:foreign','p:name','foreign');x.setAttributeNS(null,'NAME','uppercase');a.set.call(x,'\ud800');if(a.get.call(x)!=='\ud800'||x.getAttributeNS(null,'name')!=='\ud800'||x.getAttributeNS('urn:foreign','name')!=='foreign')throw 'expanded name';var clone=x.cloneNode(false),other=new Document();if(clone.name!=='\ud800'||other.adoptNode(x)!==x||x.name!=='\ud800')throw 'clone adoption';"#);}
#[test]
fn fieldset_name_conversion_once_and_canonical_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),a=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'name'),calls=0;if(!a)throw 'canonical name';Object.defineProperty(x,'name',{value:'author',configurable:true});a.set.call(x,{toString:function(){calls++;x.setAttribute('name','during');return '\udfff';}});if(calls!==1||x.name!=='author'||a.get.call(x)!=='\udfff')throw 'canonical conversion';delete x.name;var caught=false;try{x.name=Symbol('bad');}catch(e){caught=e instanceof TypeError;}if(!caught||x.name!=='\udfff')throw 'symbol rollback';try{x.name={toString:function(){throw 'abrupt';}};}catch(e){if(e!=='abrupt')throw e;}if(x.name!=='\udfff')throw 'abrupt rollback';"#);}

#[test]
fn fieldset_name_native_conversion_reentry_and_author_overrides(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('fieldset'),nd=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'name'),td=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'type'),old=output.getAttributeNode('name'),calls=0;output.name={toString:function(){calls++;output.removeAttribute('name');output.setAttribute('name','callback');return 'A\ud800z';}};var actual=output.getAttributeNode('name');if(calls!==1||actual===old||old.ownerElement!==null||old.value!=='group'||actual.value!=='A\ud800z')throw 'current actual attribute after conversion';var marker={},caught;try{output.name={toString:function(){output.setAttribute('name','effect');throw marker;}};}catch(e){caught=e;}if(caught!==marker||output.name!=='effect')throw 'abrupt completed author effects';caught=false;try{output.name=Symbol('bad');}catch(e){caught=e instanceof TypeError;}if(!caught||actual.value!=='effect')throw 'symbol conversion before publication';output.type={toString:function(){calls++;return 'bad';}};if(calls!==1||output.type!=='fieldset'||output.getAttribute('type')!==null)throw 'readonly type never converts';nd.set.call(output,null);if(output.name!=='null')throw 'null DOMString';nd.set.call(output);if(output.name!=='undefined')throw 'missing argument DOMString';var hits=0;try{nd.set.call({},{toString:function(){hits++;return 'bad';}});}catch(e){if(!(e instanceof TypeError))throw e;}if(hits)throw 'brand before conversion';Object.defineProperty(output,'name',{value:'own',writable:true,configurable:true});Object.defineProperty(output,'type',{value:'own type',writable:true,configurable:true});nd.set.call(output,'native');if(output.name!=='own'||nd.get.call(output)!=='native'||output.type!=='own type'||td.get.call(output)!=='fieldset')throw 'own author shadows';delete output.name;delete output.type;Object.defineProperty(HTMLFieldSetElement.prototype,'name',{get:function(){return 'prototype';},configurable:true});Object.defineProperty(HTMLFieldSetElement.prototype,'type',{get:function(){return 'prototype type';},configurable:true});if(output.name!=='prototype'||output.type!=='prototype type'||nd.get.call(output)!=='native'||td.get.call(output)!=='fieldset')throw 'prototype overrides';delete HTMLFieldSetElement.prototype.name;delete HTMLFieldSetElement.prototype.type;if(output.name!==undefined||output.type!==undefined||nd.get.call(output)!=='native')throw 'deleted canonical descriptors';Object.defineProperty(HTMLFieldSetElement.prototype,'name',nd);Object.defineProperty(HTMLFieldSetElement.prototype,'type',td);var count=0;for(var key in output)if(key==='name'||key==='type')count++;if(count!==2||Object.hasOwn(output,'name')||Object.hasOwn(output,'type'))throw 'inherited restored metadata';"#);}
#[test]
fn fieldset_name_writer_limits_preserve_actual_records_and_recover(){for inert in [false,true]{for expression in [r#"output.name='long A\ud800z B\udfffz';"#,r#"output.setAttribute('name','long A\ud800z B\udfffz');"#,r#"output.setAttributeNS(null,'name','long A\ud800z B\udfffz');"#,r#"attr.textContent='long A\ud800z B\udfffz';"#]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('fieldset');output.name='group';var attr=output.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"}else{"var output=document.getElementById('fieldset'),attr=output.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"});p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=0,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(output.name!=='group'||attr.value!=='group'||watch.takeRecords().length)throw 'atomic refused name write';output.name='fresh';if(output.type!=='fieldset'||attr!==output.getAttributeNode('name')||attr.value!=='fresh'||watch.takeRecords().length!==1)throw 'fresh native metadata recovery';");}}}}
#[test]
fn fieldset_name_paid_reads_and_fixed_type_string_bounds_recover(){let(mut d,mut f,mut p)=fixture();let owner=node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("fieldset")).unwrap());let state=(p.state.retained,p.state.dom_commits);let strings=p.state.limits.host.string_bytes;for property in ["name","type"]{for mode in 0..4{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.fieldset_get(owner,if property=="name"{script_fieldset::NAME_GET}else{script_fieldset::TYPE}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!((p.state.retained,p.state.dom_commits),state);p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;}}p.begin_job();run(&mut d,&mut f,&mut p,"if(document.getElementById('fieldset').name!=='group'||document.getElementById('fieldset').type!=='fieldset')throw 'fresh paid metadata reads';");}
#[test]
fn fieldset_name_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('fieldset'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var name=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFieldSetElement.prototype,'name'),type=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFieldSetElement.prototype,'type'),calls=0;name.set.call(output,'A\ud800z');if(name.get.call(output)!=='A\ud800z'||type.get.call(output)!=='fieldset')throw 'saved child metadata';"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://foreign-output-metadata.test/",&crate::navigation::Location::home()).unwrap());for expression in ["name.set.call(output,{toString:function(){calls++;return 'bad';}});","name.get.call(output);","type.get.call(output);"]{p.begin_job();let e=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://fieldset-metadata.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||output.name!=='A\\ud800z')throw 'origin before conversion';name.set.call(output,'fresh');if(output.name!=='fresh'||type.get.call(output)!=='fieldset')throw 'fresh captured metadata recovery';");}

#[test]
fn fieldset_name_exact_producers_live_names_css_and_observers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),attr=x.getAttributeNode('name'),raw=document.getElementsByName('A\ud800z'),literal=document.getElementsByName('A\ufffdz'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.name='A\ud800z';var records=watch.takeRecords();if(raw.length!==1||raw[0]!==x||literal.length||x.matches('[name=\"A\ufffdz\"]')||attr!==x.getAttributeNode('name')||attr.value!==x.name||records.length!==1||records[0].oldValue!=='group'||records[0].attributeName!=='name')throw 'exact native consumers';attr.value='A\ufffdz';if(x.name!=='A\ufffdz'||raw.length||literal.length!==1)throw 'actual Attr consumer';x.setAttributeNS(null,'name','A\ud800z');if(x.name!=='A\ud800z'||raw.length!==1||literal.length)throw 'null namespace actual producer';"#);}
